//! RV64 Zca expansion-decoder tests (issue #132, contract U1).
//!
//! An exhaustive 65,536-parcel classification check against the independent
//! pinned reference `tools/zca/zca-reference-v1.tsv` (generated by
//! `tools/zca/gen_zca_reference.py`), plus boundary-immediate coverage of
//! every compressed immediate format and regression tests for each defect
//! recorded in the issue.

use ruscv_sim::decode::{Funct3, Opcode};
use ruscv_sim::isa::rv64c::{CompressedDecoder, ZcaClass};

fn decode(parcel: u16) -> u32 {
    match CompressedDecoder::new().classify_16bit(parcel) {
        ZcaClass::Expansion { instruction } | ZcaClass::Hint { instruction } => instruction,
        other => panic!("parcel 0x{parcel:04x} classified {other:?}, expected expansion"),
    }
}

// ============== Exhaustive reference check ==============

#[test]
fn exhaustive_classification_matches_pinned_reference() {
    let decoder = CompressedDecoder::new();
    let mut line_count = 0usize;
    for (line_no, line) in include_str!("../tools/zca/zca-reference-v1.tsv")
        .lines()
        .enumerate()
    {
        let mut fields = line.split('\t');
        let parcel = u16::from_str_radix(fields.next().unwrap().trim_start_matches("0x"), 16)
            .unwrap_or_else(|_| panic!("bad parcel on line {}", line_no + 1));
        assert_eq!(
            parcel as usize, line_no,
            "reference rows must be complete and in parcel order"
        );
        line_count += 1;
        let cls = fields.next().unwrap();
        let expansion = fields.next().unwrap();
        let actual = decoder.classify_16bit(parcel);
        match cls {
            "R" => assert_eq!(
                ZcaClass::Reserved,
                actual,
                "parcel 0x{parcel:04x} must be reserved, got {actual:?}"
            ),
            "F" => assert_eq!(
                ZcaClass::FpIllegal,
                actual,
                "parcel 0x{parcel:04x} must be FP-illegal, got {actual:?}"
            ),
            cls @ ("E" | "H") => {
                let want_hint = cls == "H";
                let want = u32::from_str_radix(expansion.trim_start_matches("0x"), 16).unwrap();
                let (is_hint, got) = match actual {
                    ZcaClass::Expansion { instruction } => (false, instruction),
                    ZcaClass::Hint { instruction } => (true, instruction),
                    other => panic!("parcel 0x{parcel:04x} classified {other:?}, want {cls}"),
                };
                assert_eq!(
                    want_hint, is_hint,
                    "parcel 0x{parcel:04x}: HINT/E mismatch for expansion 0x{got:08x}"
                );
                assert_eq!(
                    want, got,
                    "parcel 0x{parcel:04x} expansion mismatch (want 0x{want:08x})"
                );
            }
            _ => panic!("bad class on line {}", line_no + 1),
        }
    }
    assert_eq!(
        line_count, 0x10000,
        "reference must cover all 65536 parcels, got {line_count}"
    );
}

// ============== Defect regressions (issue #132) ==============

#[test]
fn c0_011_and_111_are_ld_and_sd_not_flw_fsw() {
    // Regression: decoder used to map C0 funct3 011/111 to C.FLW/C.FSW.
    // C.LD x9, 8(x9): funct3=011, offset[5:3]=001, rs1'=001 (x9), rd'=001 (x9)
    let inst: u16 = 0b0110_0100_1000_0100; // 0x6484
    let exp = decode(inst);
    assert_eq!(exp, 0x0084B483, "C.LD must expand to ld x9, 8(x9)");
    // C.SD x9, 8(x9): funct3=111
    let inst: u16 = 0b1110_0100_1000_0100; // 0xE484
    let exp = decode(inst);
    assert_eq!(exp, 0x0094B423, "C.SD must expand to sd x9, 8(x9)");
}

#[test]
fn c_lw_and_c_sw_expand_as_word_not_halfword() {
    // Regression: C.LW/C.SW expanded with funct3=SLL (LH/SH).
    // C.LW x8, 0(x9): funct3=010, rs1'=001, rd'=000, offset 0
    let inst: u16 = 0b0100_0000_1000_0000; // 0x4080
    assert_eq!(decode(inst), 0x0004A403, "C.LW must expand to lw");
    // C.SW x8, 0(x9): funct3=110
    let inst: u16 = 0b1100_0000_1000_0000; // 0xC080
    assert_eq!(decode(inst), 0x0084A023, "C.SW must expand to sw");
}

#[test]
fn c_lwsp_and_c_swsp_expand_as_word_c_ldsp_sdsp_as_doubleword() {
    // Regression: SP forms expanded with the wrong widths.
    // C.LWSP x1, 0(x2): funct3=010, rd=1
    let inst: u16 = 0b0100_0000_1000_0010; // 0x4082
    assert_eq!(
        decode(inst),
        0x00012083,
        "C.LWSP must expand to lw x1, 0(x2)"
    );
    // C.LDSP x1, 0(x2): funct3=011
    let inst: u16 = 0b0110_0000_1000_0010; // 0x6082
    assert_eq!(
        decode(inst),
        0x00013083,
        "C.LDSP must expand to ld x1, 0(x2)"
    );
    // C.SWSP x1, 0(x2): funct3=110, rs2=1 -> 0xC006
    assert_eq!(
        decode(0xC006),
        0x00112023,
        "C.SWSP must expand to sw x1, 0(x2)"
    );
    // C.SDSP x1, 0(x2): funct3=111, rs2=1 -> 0xE006
    assert_eq!(
        decode(0xE006),
        0x00113023,
        "C.SDSP must expand to sd x1, 0(x2)"
    );
}

#[test]
fn c_addiw_uses_op_imm_32_not_op_32() {
    // Regression: C.ADDIW expanded to Opcode::Op32 (R-type) instead of
    // Opcode::OpImm32 (addiw).
    // C.ADDIW x1, 1: funct3=001, rd=1, imm=1
    let inst: u16 = 0b0010_0000_1000_0101; // 0x2085
    let decoded = CompressedDecoder::new().decode_16bit(inst).unwrap();
    assert_eq!(
        decoded.opcode,
        Opcode::OpImm32,
        "C.ADDIW must expand to addiw"
    );
    assert_eq!(decoded.funct3, Some(Funct3::AddSub));
    assert_eq!(decoded.rd, Some(1));
    assert_eq!(decoded.rs1, Some(1));
    assert_eq!(decoded.imm, Some(1));
    // And the raw expansion must be a valid addiw encoding.
    assert_eq!(decoded.raw, 0x0010809B);
}

#[test]
fn c_nop_and_hint_forms_are_not_reserved() {
    // Regression: C.NOP and the rd=0/imm=0 HINT forms were rejected as
    // reserved.
    let decoder = CompressedDecoder::new();
    // C.NOP (0x0001) is an ordinary legal NOP: addi x0, x0, 0.
    assert_eq!(
        decoder.classify_16bit(0x0001),
        ZcaClass::Expansion {
            instruction: 0x00000013
        }
    );
    // Every D2 HINT class classifies as Hint and decodes to a valid 32-bit
    // expansion.
    for (parcel, name) in [
        (0x0021u16, "c.nop 8 (C.ADDI rd=0, imm!=0)"),
        (0x0081, "C.ADDI rd!=0, imm=0"),
        (0x4021, "C.LI rd=0"),
        (0x0002, "C.SLLI rd=0"),
        (0x6005, "C.LUI rd=0, imm!=0"),
        (0x8006, "C.MV rd=0, rs2!=0"),
        (0x9006, "C.ADD rd=0, rs2!=0"),
        (0x8001, "C.SRLI shamt=0"),
        (0x8401, "C.SRAI shamt=0"),
    ] {
        assert!(
            matches!(decoder.classify_16bit(parcel), ZcaClass::Hint { .. }),
            "{name} must classify as HINT, got {:?}",
            decoder.classify_16bit(parcel)
        );
        assert!(
            decoder.decode_16bit(parcel).is_ok(),
            "{name} must decode, got {:?}",
            decoder.decode_16bit(parcel)
        );
    }
}

#[test]
fn fp_compressed_and_reserved_classes() {
    let decoder = CompressedDecoder::new();
    // C.FLD / C.FSD / C.FLDSP / C.FSDSP classify as FP-illegal.
    assert_eq!(
        decoder.classify_16bit(0x2480), // c.fld
        ZcaClass::FpIllegal
    );
    assert_eq!(
        decoder.classify_16bit(0xA904), // c.fsd
        ZcaClass::FpIllegal
    );
    assert_eq!(
        decoder.classify_16bit(0x2002), // c.fldsp (rd=0 is still the FP slot)
        ZcaClass::FpIllegal
    );
    assert_eq!(
        decoder.classify_16bit(0xA002), // c.fsdsp
        ZcaClass::FpIllegal
    );
    // The all-zero parcel and named reserved forms.
    assert_eq!(decoder.classify_16bit(0x0000), ZcaClass::Reserved);
    assert_eq!(decoder.classify_16bit(0x0004), ZcaClass::Reserved); // c.addi4spn imm=0
    assert_eq!(decoder.classify_16bit(0x6081), ZcaClass::Reserved); // c.lui imm=0
    assert_eq!(decoder.classify_16bit(0x6181), ZcaClass::Reserved); // c.addi16sp imm=0
    assert_eq!(decoder.classify_16bit(0x4002), ZcaClass::Reserved); // c.lwsp rd=0
    assert_eq!(decoder.classify_16bit(0x6002), ZcaClass::Reserved); // c.ldsp rd=0
    assert_eq!(decoder.classify_16bit(0x8002), ZcaClass::Reserved); // c.jr rs1=0
    assert_eq!(decoder.classify_16bit(0x2001), ZcaClass::Reserved); // c.addiw rd=0
                                                                    // All decode as errors.
    for parcel in [
        0x0000u16, 0x0004, 0x6081, 0x6181, 0x4002, 0x6002, 0x8002, 0x2001, 0x2480, 0xA904, 0x2002,
        0xA002,
    ] {
        assert!(
            decoder.decode_16bit(parcel).is_err(),
            "parcel 0x{parcel:04x} must be a decode error"
        );
    }
}

// ============== Boundary-immediate coverage ==============

#[test]
fn boundary_immediates() {
    // C.ADDI: 6-bit signed immediate, [-32, 31].
    // imm=-32 -> parcel funct3=000, bit12=1, imm[4:0]=0, rd=1: 0x1081
    assert_eq!(decode(0x1081), 0xFE008093); // addi x1, x1, -32
                                            // imm=31 -> 0x00FD -> parcel 0x00FD? imm[4:0]=31 -> bits[6:2]=11111: 0x00FD? rd=1.
    let inst: u16 = 0b0000_0000_1111_1101; // 0x00FD: c.addi x1, 31
    assert_eq!(decode(inst), 0x01F08093);

    // C.LI sign extremes.
    // c.li x2, -32: funct3=010, bit12=1, rd=2, imm[4:0]=0 -> 0x5101
    assert_eq!(decode(0x5101), 0xFE000113); // addi x2, x0, -32

    // C.LUI boundary: imm[17]=1 sign-extends to the high bits.
    // c.lui x3, imm[17:12]=0x3F: bit12=1, nzimm[16:12]=0x1F -> 0x71FD
    assert_eq!(decode(0x71FD), 0xFFFFF1B7); // lui x3, -1 (sign extreme)

    // C.ADDI16SP boundary: imm=-512 (bit12=1, others 0): 0x7101.
    // nzuimm[9]=1 -> sext -> -512; parcel funct3=011 rd=2 bit12=1 -> 0x7101
    assert_eq!(decode(0x7101), 0xE0010113); // addi x2, x2, -512

    // C.SLLI shamt=63: C2 funct3=000, bit12=1, rd=1, shamt[4:0]=0x1F -> 0x10FE
    assert_eq!(decode(0x10FE), 0x03F09093); // slli x1, x1, 63

    // C.J jump range: offset=-2048 -> 0xB001; offset=+2046 -> 0xAFFD.
    assert_eq!(decode(0xB001), 0x801FF06F); // jal x0, -2048
    assert_eq!(decode(0xAFFD), 0x7FE0006F); // jal x0, 2046

    // C.BEQZ range: offset=-256 -> 0xD001 (rs1'=000 -> x8); offset=+254 -> 0xCC7D.
    assert_eq!(decode(0xD001), 0xF00400E3); // beq x8, x0, -256
    assert_eq!(decode(0xCC7D), 0x0E040F63, "c.beqz x8, 254");
}

/// The reference generator computes these constants from its bit-layout
/// tables; each case exercises one immediate bit position or range extreme so
/// a shuffled or dropped source bit cannot slip through.
#[test]
fn immediate_bit_layouts() {
    // C.ADDI4SPN: nzuimm[5:4|9:6|3|2] <- p[12:11|10:7|5|6]
    assert_eq!(decode(0x0044), 0x00410493); // c.addi4spn x9, 4 (p6->imm2)
    assert_eq!(decode(0x1FE0), 0x3FC10413); // c.addi4spn x8, 1020 (max)
                                            // C.LW/C.SW: uimm[5:3|2|6] <- p[12:10|6|5]
    assert_eq!(decode(0x40C4), 0x0044A483); // c.lw x9, 4(x9)  (p6->imm2)
    assert_eq!(decode(0x4484), 0x0084A483); // c.lw x9, 8(x9)  (p10->imm3)
    assert_eq!(decode(0x40A4), 0x0404A483); // c.lw x9, 64(x9) (p5->imm6)
    assert_eq!(decode(0x5CE4), 0x07C4A483); // c.lw x9, 124(x9) (max)
    assert_eq!(decode(0xC484), 0x0094A423); // c.sw x9, 8(x9)
    assert_eq!(decode(0xDCE4), 0x0694AE23); // c.sw x9, 124(x9) (max)
                                            // C.LD/C.SD: uimm[5:3|7:6] <- p[12:10|6:5]
    assert_eq!(decode(0x60A4), 0x0404B483); // c.ld x9, 64(x9)  (p5->imm6)
    assert_eq!(decode(0x60C4), 0x0804B483); // c.ld x9, 128(x9) (p6->imm7)
    assert_eq!(decode(0x7CE4), 0x0F84B483); // c.ld x9, 248(x9) (max)
    assert_eq!(decode(0xE0C4), 0x0894B023); // c.sd x9, 128(x9)
    assert_eq!(decode(0xFCE4), 0x0E94BC23); // c.sd x9, 248(x9) (max)
                                            // C.LWSP: uimm[5|4:2|7:6] <- p[12|6:4|3:2]
    assert_eq!(decode(0x4092), 0x00412083); // c.lwsp x1, 4(x2)   (p4->imm2)
    assert_eq!(decode(0x4086), 0x04012083); // c.lwsp x1, 64(x2)  (p2->imm6)
    assert_eq!(decode(0x408A), 0x08012083); // c.lwsp x1, 128(x2) (p3->imm7)
    assert_eq!(decode(0x5082), 0x02012083); // c.lwsp x1, 32(x2)  (p12->imm5)
    assert_eq!(decode(0x50FE), 0x0FC12083); // c.lwsp x1, 252(x2) (max)
                                            // C.LDSP: uimm[5|4:3|8:6] <- p[12|6:5|4:2]
    assert_eq!(decode(0x60A2), 0x00813083); // c.ldsp x1, 8(x2)   (p5->imm3)
    assert_eq!(decode(0x6086), 0x04013083); // c.ldsp x1, 64(x2)  (p2->imm6)
    assert_eq!(decode(0x6092), 0x10013083); // c.ldsp x1, 256(x2) (p4->imm8)
    assert_eq!(decode(0x70FE), 0x1F813083); // c.ldsp x1, 504(x2) (max)
                                            // C.SWSP: uimm[5:2|7:6] <- p[12:9|8:7]
    assert_eq!(decode(0xC206), 0x00112223); // c.swsp x1, 4(x2)   (p9->imm2)
    assert_eq!(decode(0xC086), 0x04112023); // c.swsp x1, 64(x2)  (p7->imm6)
    assert_eq!(decode(0xC106), 0x08112023); // c.swsp x1, 128(x2) (p8->imm7)
    assert_eq!(decode(0xC806), 0x00112823); // c.swsp x1, 16(x2)  (p11->imm4)
    assert_eq!(decode(0xDF86), 0x0E112E23); // c.swsp x1, 252(x2) (max)
                                            // C.SDSP: uimm[5:3|8:6] <- p[12:10|9:7]
    assert_eq!(decode(0xE406), 0x00113423); // c.sdsp x1, 8(x2)   (p10->imm3)
    assert_eq!(decode(0xE086), 0x04113023); // c.sdsp x1, 64(x2)  (p7->imm6)
    assert_eq!(decode(0xE206), 0x10113023); // c.sdsp x1, 256(x2) (p9->imm8)
    assert_eq!(decode(0xFF86), 0x1E113C23); // c.sdsp x1, 504(x2) (max)
                                            // C.ADDI16SP signed extremes: nzuimm[9|4|6|8:7|5] <- p[12|6|5|4:3|2]
    assert_eq!(decode(0x617D), 0x1F010113); // c.addi16sp +496 (max)
    assert_eq!(decode(0x7101), 0xE0010113); // c.addi16sp -512 (min)
                                            // C.LUI signed extremes: nzimm[17|16:12] <- p[12|6:2]
    assert_eq!(decode(0x60FD), 0x0001F0B7); // c.lui x1, 0x1F (max positive)
    assert_eq!(decode(0x71FD), 0xFFFFF1B7); // c.lui x1, -1 (sign extreme)
}
